/* @lc app=leetcode id=3811 lang=kotlin */ class Solution { fun alternatingXOR(nums: IntArray, target1: Int, target2: Int): Int = 1_000_000_007L.let { M -> HashMap<Int, Long>().also { it[0] = 1L }.let { mA -> HashMap<Int, Long>().let { mB -> nums.fold(Triple(0, 0L, 0L)) { (p, _, _), x -> (p xor x).let { np -> (mA[np xor target1] ?: 0L).let { f1 -> (mB[np xor target2] ?: 0L).let { f2 -> mA.merge(np, f2) { a, b -> (a + b) % M }.also { mB.merge(np, f1) { a, b -> (a + b) % M } }.let { Triple(np, f1, f2) } } } } } }.let { ((it.second + it.third) % M).toInt() } } } }